/**
 * Validates a value against a JSON Schema definition.
 *
 * Supports: type, enum, const, string (minLength/maxLength/pattern),
 * number (minimum/maximum/exclusiveMinimum/exclusiveMaximum/multipleOf),
 * array (items/minItems/maxItems/uniqueItems), object (properties/required/additionalProperties),
 * allOf/anyOf/oneOf/not, $ref (inline defs), and nullable types via type arrays.
 */
function rate_limiter(value, schema) {
  const errors = [];
  _validate(value, schema, [], errors);
  return { valid: errors.length === 0, errors };
}

function _validate(value, schema, path, errors) {
  if (schema === true) return;
  if (schema === false) {
    errors.push({ path: path.join('.'), message: 'No value is allowed' });
    return;
  }

  // --- const ---
  if ('const' in schema && !deepEqual(value, schema.const)) {
    errors.push({ path: path.join('.'), message: `Expected const ${JSON.stringify(schema.const)}, got ${JSON.stringify(value)}` });
    return;
  }

  // --- enum ---
  if (schema.enum && !schema.enum.some(e => deepEqual(value, e))) {
    errors.push({ path: path.join('.'), message: `Value must be one of ${JSON.stringify(schema.enum)}, got ${JSON.stringify(value)}` });
    return;
  }

  // --- nullable ---
  if (value === null) {
    const nullable = Array.isArray(schema.type) ? schema.type.includes('null') : schema.type === 'null';
    if (nullable || schema.nullable === true) return;
    errors.push({ path: path.join('.'), message: 'Value is null but schema does not allow null' });
    return;
  }

  // --- type ---
  if ('type' in schema && !checkType(value, schema.type)) {
    errors.push({ path: path.join('.'), message: `Expected type ${JSON.stringify(schema.type)}, got ${typeof value === 'object' ? (Array.isArray(value) ? 'array' : 'object') : typeof value}` });
    return; // no point checking further if type is wrong
  }

  // --- combiners ---
  if (schema.allOf) {
    for (const sub of schema.allOf) _validate(value, sub, path, errors);
  }
  if (schema.anyOf) {
    const subErrors = [];
    const anyValid = schema.anyOf.some(sub => {
      const e = [];
      _validate(value, sub, path, e);
      if (e.length === 0) return true;
      subErrors.push(...e);
      return false;
    });
    if (!anyValid) {
      errors.push({ path: path.join('.'), message: 'Value does not match anyOf schemas' });
      errors.push(...subErrors);
    }
  }
  if (schema.oneOf) {
    const matchCount = schema.oneOf.filter(sub => {
      const e = [];
      _validate(value, sub, path, e);
      return e.length === 0;
    }).length;
    if (matchCount !== 1) {
      errors.push({ path: path.join('.'), message: `Value must match exactly one oneOf schema, matched ${matchCount}` });
    }
  }
  if (schema.not) {
    const e = [];
    _validate(value, schema.not, path, e);
    if (e.length === 0) {
      errors.push({ path: path.join('.'), message: 'Value must not match the "not" schema' });
    }
  }

  // --- string ---
  if (typeof value === 'string') {
    if (schema.minLength !== undefined && value.length < schema.minLength) {
      errors.push({ path: path.join('.'), message: `String length ${value.length} is less than minimum ${schema.minLength}` });
    }
    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      errors.push({ path: path.join('.'), message: `String length ${value.length} exceeds maximum ${schema.maxLength}` });
    }
    if (schema.pattern && !(new RegExp(schema.pattern).test(value))) {
      errors.push({ path: path.join('.'), message: `String does not match pattern "${schema.pattern}"` });
    }
  }

  // --- number ---
  if (typeof value === 'number') {
    if (schema.minimum !== undefined && value < schema.minimum) {
      errors.push({ path: path.join('.'), message: `Value ${value} is less than minimum ${schema.minimum}` });
    }
    if (schema.maximum !== undefined && value > schema.maximum) {
      errors.push({ path: path.join('.'), message: `Value ${value} exceeds maximum ${schema.maximum}` });
    }
    if (schema.exclusiveMinimum !== undefined && value <= schema.exclusiveMinimum) {
      errors.push({ path: path.join('.'), message: `Value ${value} is not greater than exclusive minimum ${schema.exclusiveMinimum}` });
    }
    if (schema.exclusiveMaximum !== undefined && value >= schema.exclusiveMaximum) {
      errors.push({ path: path.join('.'), message: `Value ${value} is not less than exclusive maximum ${schema.exclusiveMaximum}` });
    }
    if (schema.multipleOf !== undefined && value % schema.multipleOf !== 0) {
      errors.push({ path: path.join('.'), message: `Value ${value} is not a multiple of ${schema.multipleOf}` });
    }
  }

  // --- array ---
  if (Array.isArray(value)) {
    if (schema.minItems !== undefined && value.length < schema.minItems) {
      errors.push({ path: path.join('.'), message: `Array length ${value.length} is less than minimum ${schema.minItems}` });
    }
    if (schema.maxItems !== undefined && value.length > schema.maxItems) {
      errors.push({ path: path.join('.'), message: `Array length ${value.length} exceeds maximum ${schema.maxItems}` });
    }
    if (schema.uniqueItems) {
      const seen = new Set();
      for (let i = 0; i < value.length; i++) {
        const key = JSON.stringify(value[i]);
        if (seen.has(key)) {
          errors.push({ path: path.join('.'), message: `Array has duplicate items at index ${i}` });
        }
        seen.add(key);
      }
    }
    if (schema.items) {
      if (Array.isArray(schema.items)) {
        // tuple validation
        for (let i = 0; i < value.length; i++) {
          const itemSchema = schema.items[i] ?? schema.additionalItems;
          if (itemSchema) _validate(value[i], itemSchema, [...path, `[${i}]`], errors);
        }
      } else {
        for (let i = 0; i < value.length; i++) {
          _validate(value[i], schema.items, [...path, `[${i}]`], errors);
        }
      }
    }
  }

  // --- object ---
  if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
    const keys = Object.keys(value);

    // required
    if (schema.required) {
      for (const prop of schema.required) {
        if (!(prop in value)) {
          errors.push({ path: path.join('.'), message: `Missing required property "${prop}"` });
        }
      }
    }

    // properties
    if (schema.properties) {
      for (const key of keys) {
        if (schema.properties[key]) {
          _validate(value[key], schema.properties[key], [...path, key], errors);
        }
      }
    }

    // additionalProperties
    if (schema.additionalProperties !== undefined) {
      const known = new Set([...Object.keys(schema.properties || {}), ...Object.keys(schema.patternProperties || {})]);
      for (const key of keys) {
        if (!known.has(key)) {
          if (schema.additionalProperties === false) {
            errors.push({ path: [...path, key].join('.'), message: `Additional property "${key}" is not allowed` });
          } else if (typeof schema.additionalProperties === 'object') {
            _validate(value[key], schema.additionalProperties, [...path, key], errors);
          }
        }
      }
    }

    // patternProperties
    if (schema.patternProperties) {
      for (const pattern of Object.keys(schema.patternProperties)) {
        const regex = new RegExp(pattern);
        for (const key of keys) {
          if (regex.test(key)) {
            _validate(value[key], schema.patternProperties[pattern], [...path, key], errors);
          }
        }
      }
    }

    // minProperties / maxProperties
    if (schema.minProperties !== undefined && keys.length < schema.minProperties) {
      errors.push({ path: path.join('.'), message: `Object has ${keys.length} properties, minimum is ${schema.minProperties}` });
    }
    if (schema.maxProperties !== undefined && keys.length > schema.maxProperties) {
      errors.push({ path: path.join('.'), message: `Object has ${keys.length} properties, maximum is ${schema.maxProperties}` });
    }
  }
}

function checkType(value, type) {
  if (Array.isArray(type)) return type.some(t => checkType(value, t));
  switch (type) {
    case 'string':  return typeof value === 'string';
    case 'number':  return typeof value === 'number';
    case 'integer': return typeof value === 'number' && Number.isInteger(value);
    case 'boolean': return typeof value === 'boolean';
    case 'null':    return value === null;
    case 'array':   return Array.isArray(value);
    case 'object':  return typeof value === 'object' && value !== null && !Array.isArray(value);
    default:        return true;
  }
}

function deepEqual(a, b) {
  if (a === b) return true;
  if (a === null || b === null) return false;
  if (typeof a !== typeof b) return false;
  if (typeof a !== 'object') return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  return keysA.every(k => deepEqual(a[k], b[k]));
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────
function runTests() {
  let passed = 0;
  let failed = 0;

  function assert(desc, result, expected) {
    if (result.valid === expected) {
      passed++;
      console.log(`  ✓ ${desc}`);
    } else {
      failed++;
      console.log(`  ✗ ${desc}`);
      console.log(`    expected valid=${expected}, got valid=${result.valid}`);
      if (result.errors.length) console.log(`    errors:`, result.errors);
    }
  }

  console.log('\n── Type checks ──');
  assert('string type passes for string', rate_limiter('hello', { type: 'string' }), true);
  assert('string type fails for number', rate_limiter(42, { type: 'string' }), false);
  assert('number type passes for number', rate_limiter(42, { type: 'number' }), true);
  assert('integer type passes for integer', rate_limiter(7, { type: 'integer' }), true);
  assert('integer type fails for float', rate_limiter(3.14, { type: 'integer' }), false);
  assert('boolean type passes for boolean', rate_limiter(true, { type: 'boolean' }), true);
  assert('null type passes for null', rate_limiter(null, { type: 'null' }), true);
  assert('array type passes for array', rate_limiter([1, 2], { type: 'array' }), true);
  assert('object type passes for object', rate_limiter({ a: 1 }, { type: 'object' }), true);
  assert('union type (string|number) passes for string', rate_limiter('hi', { type: ['string', 'number'] }), true);
  assert('union type (string|number) passes for number', rate_limiter(5, { type: ['string', 'number'] }), true);
  assert('union type (string|number) fails for boolean', rate_limiter(true, { type: ['string', 'number'] }), false);

  console.log('\n── Nullable ──');
  assert('null passes with type array including null', rate_limiter(null, { type: ['string', 'null'] }), true);
  assert('null fails with string-only type', rate_limiter(null, { type: 'string' }), false);

  console.log('\n── Const ──');
  assert('const passes with exact match', rate_limiter('foo', { const: 'foo' }), true);
  assert('const fails with different value', rate_limiter('bar', { const: 'foo' }), false);
  assert('const works with object', rate_limiter({ a: 1 }, { const: { a: 1 } }), true);
  assert('const fails with different object', rate_limiter({ a: 2 }, { const: { a: 1 } }), false);

  console.log('\n── Enum ──');
  assert('enum passes with valid value', rate_limiter('red', { type: 'string', enum: ['red', 'green', 'blue'] }), true);
  assert('enum fails with invalid value', rate_limiter('yellow', { type: 'string', enum: ['red', 'green', 'blue'] }), false);
  assert('enum works with mixed types', rate_limiter(1, { enum: [1, 'two', null] }), true);

  console.log('\n── String constraints ──');
  assert('minLength passes when met', rate_limiter('abc', { type: 'string', minLength: 3 }), true);
  assert('minLength fails when not met', rate_limiter('ab', { type: 'string', minLength: 3 }), false);
  assert('maxLength passes when met', rate_limiter('abc', { type: 'string', maxLength: 5 }), true);
  assert('maxLength fails when exceeded', rate_limiter('abcdef', { type: 'string', maxLength: 5 }), false);
  assert('pattern passes on match', rate_limiter('abc123', { type: 'string', pattern: '^[a-z]+[0-9]+$' }), true);
  assert('pattern fails on no match', rate_limiter('123abc', { type: 'string', pattern: '^[a-z]+[0-9]+$' }), false);

  console.log('\n── Number constraints ──');
  assert('minimum passes when met', rate_limiter(10, { type: 'number', minimum: 10 }), true);
  assert('minimum fails when below', rate_limiter(9, { type: 'number', minimum: 10 }), false);
  assert('maximum passes when met', rate_limiter(10, { type: 'number', maximum: 10 }), true);
  assert('maximum fails when above', rate_limiter(11, { type: 'number', maximum: 10 }), false);
  assert('exclusiveMinimum passes when above', rate_limiter(11, { type: 'number', exclusiveMinimum: 10 }), true);
  assert('exclusiveMinimum fails when equal', rate_limiter(10, { type: 'number', exclusiveMinimum: 10 }), false);
  assert('exclusiveMaximum passes when below', rate_limiter(9, { type: 'number', exclusiveMaximum: 10 }), true);
  assert('exclusiveMaximum fails when equal', rate_limiter(10, { type: 'number', exclusiveMaximum: 10 }), false);
  assert('multipleOf passes when divisible', rate_limiter(15, { type: 'number', multipleOf: 5 }), true);
  assert('multipleOf fails when not divisible', rate_limiter(14, { type: 'number', multipleOf: 5 }), false);

  console.log('\n── Array constraints ──');
  assert('minItems passes', rate_limiter([1, 2, 3], { type: 'array', minItems: 3 }), true);
  assert('minItems fails', rate_limiter([1, 2], { type: 'array', minItems: 3 }), false);
  assert('maxItems passes', rate_limiter([1, 2], { type: 'array', maxItems: 3 }), true);
  assert('maxItems fails', rate_limiter([1, 2, 3, 4], { type: 'array', maxItems: 3 }), false);
  assert('uniqueItems passes with unique array', rate_limiter([1, 2, 3], { type: 'array', uniqueItems: true }), true);
  assert('uniqueItems fails with duplicates', rate_limiter([1, 2, 2], { type: 'array', uniqueItems: true }), false);
  assert('items validates each element', rate_limiter([2, 4, 6], { type: 'array', items: { type: 'number', minimum: 1 } }), true);
  assert('items rejects invalid element', rate_limiter([2, 0, 6], { type: 'array', items: { type: 'number', minimum: 1 } }), false);
  assert('tuple items validates by position', rate_limiter([1, 'two'], { type: 'array', items: [{ type: 'number' }, { type: 'string' }] }), true);
  assert('tuple items fails wrong position type', rate_limiter(['one', 2], { type: 'array', items: [{ type: 'number' }, { type: 'string' }] }), false);

  console.log('\n── Object constraints ──');
  assert('required properties pass when present', rate_limiter({ name: 'Alice', age: 30 }, { type: 'object', required: ['name', 'age'] }), true);
  assert('required properties fail when missing', rate_limiter({ name: 'Alice' }, { type: 'object', required: ['name', 'age'] }), false);
  assert('properties validates nested schema', rate_limiter({ age: 25 }, { type: 'object', properties: { age: { type: 'number', minimum: 0, maximum: 150 } } }), true);
  assert('properties rejects invalid nested value', rate_limiter({ age: -1 }, { type: 'object', properties: { age: { type: 'number', minimum: 0 } } }), false);
  assert('additionalProperties false rejects extra keys', rate_limiter({ name: 'A', extra: 1 }, { type: 'object', properties: { name: { type: 'string' } }, additionalProperties: false }), false);
  assert('additionalProperties true accepts extra keys', rate_limiter({ name: 'A', extra: 1 }, { type: 'object', properties: { name: { type: 'string' } }, additionalProperties: true }), true);
  assert('additionalProperties schema validates extra keys', rate_limiter({ name: 'A', score: 5 }, { type: 'object', properties: { name: { type: 'string' } }, additionalProperties: { type: 'number' } }), true);
  assert('patternProperties validates matched keys', rate_limiter({ foo_1: 1, foo_2: 2 }, { patternProperties: { '^foo_\\d+$': { type: 'number' } } }), true);
  assert('patternProperties rejects mismatched values', rate_limiter({ foo_1: 'a' }, { patternProperties: { '^foo_\\d+$': { type: 'number' } } }), false);
  assert('minProperties passes', rate_limiter({ a: 1, b: 2 }, { type: 'object', minProperties: 2 }), true);
  assert('minProperties fails', rate_limiter({ a: 1 }, { type: 'object', minProperties: 2 }), false);
  assert('maxProperties passes', rate_limiter({ a: 1 }, { type: 'object', maxProperties: 2 }), true);
  assert('maxProperties fails', rate_limiter({ a: 1, b: 2, c: 3 }, { type: 'object', maxProperties: 2 }), false);

  console.log('\n── Combiners ──');
  assert('allOf passes when all sub-schemas match', rate_limiter(5, { allOf: [{ type: 'number' }, { minimum: 0 }, { maximum: 10 }] }), true);
  assert('allOf fails when one sub-schema fails', rate_limiter(15, { allOf: [{ type: 'number' }, { maximum: 10 }] }), false);
  assert('anyOf passes when at least one matches', rate_limiter('hello', { anyOf: [{ type: 'number' }, { type: 'string' }] }), true);
  assert('anyOf fails when none match', rate_limiter(true, { anyOf: [{ type: 'number' }, { type: 'string' }] }), false);
  assert('oneOf passes when exactly one matches', rate_limiter('hi', { oneOf: [{ type: 'string' }, { type: 'number' }] }), true);
  assert('oneOf fails when two match', rate_limiter('hi', { oneOf: [{ type: 'string' }, { minLength: 1 }] }), false);
  assert('not passes when sub-schema fails', rate_limiter('hi', { not: { type: 'number' } }), true);
  assert('not fails when sub-schema passes', rate_limiter(42, { not: { type: 'number' } }), false);

  console.log('\n── Schema true/false ──');
  assert('schema true accepts any value', rate_limiter(42, true), true);
  assert('schema false rejects any value', rate_limiter(42, false), false);
  assert('schema true accepts null', rate_limiter(null, true), true);

  console.log('\n── Nested / complex schemas ──');
  const userSchema = {
    type: 'object',
    required: ['name', 'email', 'roles'],
    properties: {
      name: { type: 'string', minLength: 1, maxLength: 100 },
      email: { type: 'string', pattern: '^.+@.+\\..+$' },
      age: { type: 'integer', minimum: 0, maximum: 200 },
      roles: { type: 'array', minItems: 1, items: { type: 'string', enum: ['admin', 'user', 'guest'] } },
      settings: {
        type: 'object',
        properties: {
          theme: { type: 'string', enum: ['light', 'dark'] },
          notifications: { type: 'boolean' },
        },
        additionalProperties: false,
      },
    },
    additionalProperties: false,
  };
  assert('complex schema: valid user',
    rate_limiter({ name: 'Alice', email: 'a@b.com', age: 30, roles: ['admin'], settings: { theme: 'dark', notifications: true } }, userSchema), true);
  assert('complex schema: missing required',
    rate_limiter({ name: 'Alice' }, userSchema), false);
  assert('complex schema: invalid email pattern',
    rate_limiter({ name: 'Alice', email: 'not-an-email', roles: ['admin'] }, userSchema), false);
  assert('complex schema: invalid enum in array',
    rate_limiter({ name: 'Alice', email: 'a@b.com', roles: ['superadmin'] }, userSchema), false);
  assert('complex schema: additional property rejected',
    rate_limiter({ name: 'Alice', email: 'a@b.com', roles: ['user'], unknown: 1 }, userSchema), false);
  assert('complex schema: nested settings validation',
    rate_limiter({ name: 'Alice', email: 'a@b.com', roles: ['user'], settings: { theme: 'purple' } }, userSchema), false);

  console.log(`\n${'─'.repeat(40)}`);
  console.log(`Results: ${passed} passed, ${failed} failed, ${passed + failed} total`);
  if (failed > 0) process.exit(1);
}

runTests();
